'),('homophone_ces_ses','Homophones ces / ses','orthographe_grammaticale',8,'B1'),('homophone_ou_ou','Homophones ou / où','orthographe_lexicale',7,'A2'),('chaine_accords_phrase','Contrôler les chaînes d’accords','expression_ecrite',8,'B1'),('revision_present_gn','Réviser un paragraphe au présent','expression_ecrite',8,'B1'),('comprendre_description_present','Comprendre une description au présent','comprehension_ecrite',7,'A2'))
insert into public.competency_nodes(key,strand,label_fr,description_fr,atomicity_level,native_grade_min,native_grade_max,cefr_min,cefr_max,generation_type,review_status)
select key,strand,label,label,4,grade,least(12,grade+2),cefr,cefr,'human','human_approved' from seed
