insert into public.competency_edges(source_node_id,target_node_id,edge_type,strength,generation_type)
select s.id,t.id,'prerequisite',1,'human' from seed join public.competency_nodes s on s.key=source_key join public.competency_nodes t on t.key=target_key
where not exists(select 1 from public.competency_edges e where e.source_node_id=s.id and e.target_node_id=t.id and e.edge_type='prerequisite');

with seed(key,label,node_key,pattern) as (values
