insert into public.misconceptions(key,label_fr,description_fr,strand,primary_node_id,diagnostic_signature,active)
select seed.key,seed.label,seed.label,n.strand,n.id,jsonb_build_object('pattern',seed.pattern),true from seed join public.competency_nodes n on n.key=seed.node_key
